import sys
import math

def kth_smallest_divisor(n, k):
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    divisors.sort()
    if len(divisors) < k:
        return -1
    else:
        return divisors[k - 1]

