def kth_smallest_divisor(n, k):
    def count_divisors(x):
        count = 0
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                if i * i == x:
                    count += 1
                else:
                    count += 2
        return count

    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        if count_divisors(mid) < k:
            low = mid + 1
        else:
            high = mid - 1

    for i in range(low, n + 1):
        if n % i == 0:
            k -= 1
            if k == 0:
                return i

    return -1

